from collections import Counter, defaultdict

def _components(g, bg):
    h, w = len(g), len(g[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            col = g[r][c]
            if col == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for a, b in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= a < h and 0 <= b < w and (a,b) not in seen and g[a][b] == col:
                        seen.add((a,b))
                        stack.append((a,b))
            out.append((col, frozenset(cells)))
    return out

def _shape(cells):
    r0 = min(r for r,c in cells)
    c0 = min(c for r,c in cells)
    return frozenset((r-r0,c-c0) for r,c in cells)

def _rect(cells):
    return (min(r for r,c in cells), max(r for r,c in cells),
            min(c for r,c in cells), max(c for r,c in cells))

def _l_open_box(cells):
    """Return the open quadrant for an exact one-cell-thick corner L, else None."""
    r0,r1,c0,c1 = _rect(cells)
    h, w = r1-r0+1, c1-c0+1
    if h < 2 or w < 2 or len(cells) != h+w-1:
        return None
    # Identify the corner where the two complete arms meet.
    for cr in (r0,r1):
        for cc in (c0,c1):
            row_arm = {(cr,c) for c in range(c0,c1+1)}
            col_arm = {(r,cc) for r in range(r0,r1+1)}
            if cells == row_arm | col_arm:
                # Open rectangle opposite the corner.
                rr0, rr1 = (r0+1,r1) if cr == r0 else (r0,r1-1)
                cc0, cc1 = (c0+1,c1) if cc == c0 else (c0,c1-1)
                return (rr0,rr1,cc0,cc1)
    return None

def transform(grid):
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    objs = _components(grid, bg)

    # An L-shaped marker frames a small example in its open quadrant. Find an
    # identical silhouette elsewhere and recolor that copy to the marker color.
    for marker_color, marker in sorted(objs, key=lambda z: -len(z[1])):
        cavity = _l_open_box(marker)
        if cavity is None:
            continue
        r0,r1,c0,c1 = cavity
        samples = [(color,cells) for color,cells in objs
                   if cells != marker and all(r0 <= r <= r1 and c0 <= c <= c1 for r,c in cells)]
        for sample_color, sample in samples:
            wanted = _shape(sample)
            copies = [(color,cells) for color,cells in objs
                      if cells != marker and cells != sample and _shape(cells) == wanted]
            if copies:
                # Recolor the matching copy outside the marker's cavity.
                for _, cells in copies:
                    for r,c in cells:
                        out[r][c] = marker_color
                return out

    # Some markers have a stepped outline rather than a simple L. Fill a small
    # contrasting component embedded in the concavity of the largest object.
    if objs:
        marker_color, marker = max(objs, key=lambda z: len(z[1]))
        r0,r1,c0,c1 = _rect(marker)
        for color,cells in objs:
            if color == marker_color or len(cells) < 2:
                continue
            if all(r0 <= r <= r1 and c0 <= c <= c1 for r,c in cells):
                # Require the component to be in a non-full part of the marker bbox.
                if any((r,c) not in marker for r,c in cells):
                    for r,c in cells:
                        out[r][c] = marker_color
                    return out
    return out
